const userPrefs = { theme: 'dark', fontSize: 16 };

// Write to Storage (Must stringify objects!)
localStorage.setItem('prefs', JSON.stringify(userPrefs));

// Read from Storage (Must parse strings!)
const savedData = localStorage.getItem('prefs');
if (savedData) {
  const parsed = JSON.parse(savedData);
  console.log('User prefers:', parsed.theme);
}

// Remove a specific item
localStorage.removeItem('prefs');

